// ─── Language Dropdown (welcome screen) ───────────────────────────────────────

function LanguageDropdown({ value, onChange }: { value: LangCode; onChange: (l: LangCode) => void }) {
  const [open, setOpen] = useState(false)
  const rootRef = useRef<HTMLDivElement>(null)
  const current = ONBOARD_LANGUAGES.find(l => l.code === value) ?? ONBOARD_LANGUAGES[0]

  useEffect(() => {
    function handleOutside(e: MouseEvent) {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false)
    }
    document.addEventListener('mousedown', handleOutside)
    return () => document.removeEventListener('mousedown', handleOutside)
  }, [])

  return (
    <div ref={rootRef} className="relative w-full">
      <button
        type="button"
        onClick={() => setOpen(o => !o)}
        aria-haspopup="listbox"
        aria-expanded={open}
        className="flex w-full items-center justify-between rounded-2xl px-4 py-3.5 transition-all active:scale-[0.98]"
        style={{ background: 'rgba(47,110,125,0.07)', border: '1.5px solid rgba(47,110,125,0.2)' }}
      >
        <span className="flex items-center gap-2.5">
          <span className="text-xl leading-none">{LANGUAGE_ICONS[current.code]}</span>
          <span className="text-sm font-extrabold" style={{ color: '#1E3B40' }}>{current.label}</span>
          <span className="text-xs font-semibold" style={{ color: '#6F93A0', fontFamily: 'DM Sans, sans-serif' }}>{current.sub}</span>
        </span>
        <span
          className="shrink-0 transition-transform duration-200"
          style={{ color: '#2F6E7D', transform: open ? 'rotate(180deg)' : 'rotate(0deg)' }}
        >
          <ChevronDown />
        </span>
      </button>

      {open && (
        <div
          className="scrollbar-hide absolute bottom-full left-0 right-0 z-20 mb-2 max-h-60 overflow-y-auto rounded-2xl p-1.5 shadow-xl"
          style={{ background: '#F7F3E8', border: '1.5px solid #DDD3B0' }}
          role="listbox"
        >
          {ONBOARD_LANGUAGES.map(l => {
            const active = l.code === value
            return (
              <button
                key={l.code}
                type="button"
                role="option"
                aria-selected={active}
                onClick={() => { onChange(l.code); setOpen(false) }}
                className="flex w-full items-center gap-2.5 rounded-xl px-3 py-2.5 text-left transition-all active:scale-[0.98]"
                style={{ background: active ? '#EEF2FF' : 'transparent' }}
              >
                <span className="text-lg leading-none">{LANGUAGE_ICONS[l.code]}</span>
                <span className="flex-1 text-sm font-bold" style={{ color: active ? '#2F6E7D' : '#1E3B40' }}>{l.label}</span>
                <span className="text-xs font-semibold" style={{ color: '#6F93A0', fontFamily: 'DM Sans, sans-serif' }}>{l.sub}</span>
                {active && <span style={{ color: '#2F6E7D' }}>✓</span>}
              </button>
            )
          })}
        </div>
      )}
    </div>
  )
}

